stop = {"TAA","TAG","TGA"}

def orfs(s, label):
    res=[]
    n=len(s)
    for f in range(3):
        i=f
        start=None
        while i < n-2:
            cod=s[i:i+3]
            if start is None:
                if cod=="ATG":
                    start=i
            else:
                if cod in stop:
                    res.append((label,f,start,i+3,i+3-start))
                    start=None
            i+=3
        if start is not None:
            res.append((label,f,start,n,n-start))
    return res

