n=len(seq)

# tandem repeat detection: find repeated k-mers occurring multiple times in tandem
def tandem(unit_min=2, unit_max=30, min_copies=3):
    found=[]
    for u in range(unit_min, unit_max+1):
        i=0
        while i+u<=n:
            unit=seq[i:i+u]
            cnt=1
            j=i+u
            while seq[j:j+u]==unit:
                cnt+=1; j+=u
            if cnt>=min_copies:
                found.append((i+1,cnt,unit,u*cnt))
                i=j
            else:
                i+=1
    return found

