seq = "".join(l.strip() for l in open("region.fasta") if not l.startswith(">")).upper()
n=len(seq)
# exact repeats length 12-17 with all positions
def find_all(L):
    from collections import defaultdict
    d=defaultdict(list)
    for i in range(n-L+1):
        d[seq[i:i+L]].append(i+1)
    reps={k:v for k,v in d.items() if len(v)>1}
    return reps
for L in (17,16,15,14,13,12):
